// Tests for core/bridges. Evidence label: unit tests only. Expected values come from tools/bridges_ref.py (brute-force removal of every edge and
// every node for the small graphs, chain decomposition and a bridge path cover for the max-size graphs and as a cross-check on the mid graphs).
// Every success test uses a scratch array of exactly 8 * nodes + 2 * edges + 1 words (filled with garbage), an is_bridge array of exactly `edges`
// bytes and an is_cut array of exactly `nodes` bytes, both pre-filled with a sentinel. Tiny or null buffers appear only for NullArgument, TooLarge,
// ScratchTooSmall and BadNode failures and for empty graphs. No test asserts any scratch value after a call. The max-size cases are sampled
// patterns, not exhaustive, and are checked by digest, by closed form and by a removal oracle on sampled edges and nodes. Time is not measured.
